import io, os, urllib.request
from pathlib import Path
import torch
import torch.nn as nn
from fastapi import FastAPI, File, HTTPException, UploadFile
from fastapi.responses import HTMLResponse
from PIL import Image, UnidentifiedImageError
from torchvision import models, transforms

APP_DIR=Path(__file__).resolve().parent
ORIGINAL_MODEL=APP_DIR/"Best_Pneumonia_Model.pth"
FALLBACK_MODEL=APP_DIR/"fallback_pneumonia_resnet50.pth"
FALLBACK_MODEL_URL=os.getenv("MODEL_URL","https://huggingface.co/mdsajjadullah/chest-xray-pneumonia-resnet50/resolve/main/best_ResNet-50_.pth?download=true")
DEVICE=torch.device("cpu")
MAX_UPLOAD_BYTES=10*1024*1024

transform=transforms.Compose([
    transforms.Resize((224,224)),
    transforms.ToTensor(),
    transforms.Normalize([0.485,0.456,0.406],[0.229,0.224,0.225]),
])

def download_fallback():
    if FALLBACK_MODEL.exists() and FALLBACK_MODEL.stat().st_size>1000: return
    urllib.request.urlretrieve(FALLBACK_MODEL_URL,FALLBACK_MODEL)

def load_original(path):
    model=models.resnet50(weights=None)
    model.fc=nn.Sequential(
        nn.Linear(model.fc.in_features,512),
        nn.ReLU(),
        nn.Dropout(0.5),
        nn.Linear(512,2),
    )
    model.load_state_dict(torch.load(path,map_location=DEVICE))
    model.to(DEVICE).eval()
    return model,"original"

def load_fallback(path):
    model=models.resnet50(weights=None)
    model.fc=nn.Sequential(nn.Dropout(0.4),nn.Linear(2048,2))
    model.load_state_dict(torch.load(path,map_location=DEVICE))
    model.to(DEVICE).eval()
    return model,"fallback"

def build_model():
    if ORIGINAL_MODEL.exists():
        try: return load_original(ORIGINAL_MODEL)
        except Exception: pass
    download_fallback()
    return load_fallback(FALLBACK_MODEL)

MODEL,MODEL_SOURCE=build_model()
DASHBOARD_HTML="<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>AUTOlab | تحليل أشعة الصدر بالذكاء الاصطناعي</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;800&family=JetBrains+Mono:wght@500&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--bg:#050b1a;--panel:#0b1630;--line:rgba(80,140,255,.22);--blue:#1560ff;--cyan:#22d3ee;--text:#e6efff;--mut:#8fa3c7;\n--g:#22c55e;--y:#facc15;--o:#fb923c;--r:#ef4444}\n*{box-sizing:border-box;margin:0}\nbody{font-family:Cairo,Tahoma,sans-serif;background:var(--bg);color:var(--text);min-height:100vh;\nbackground-image:radial-gradient(900px 500px at 85% -10%,rgba(21,96,255,.35),transparent 60%),radial-gradient(700px 400px at 0% 100%,rgba(34,211,238,.18),transparent 60%),\nlinear-gradient(rgba(80,140,255,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(80,140,255,.06) 1px,transparent 1px);\nbackground-size:auto,auto,40px 40px,40px 40px}\n.wrap{max-width:1100px;margin:0 auto;padding:28px 18px 50px}\nheader{text-align:center;margin-bottom:22px}\n.chip{display:inline-flex;gap:8px;align-items:center;font:500 12px 'JetBrains Mono',monospace;color:var(--cyan);border:1px solid var(--line);padding:5px 12px;border-radius:99px;background:rgba(34,211,238,.06)}\n.chip i{width:7px;height:7px;border-radius:50%;background:var(--cyan);box-shadow:0 0 10px var(--cyan);animation:pulse 1.6s infinite}\nh1{font-size:clamp(26px,5vw,44px);font-weight:800;margin:14px 0 6px;background:linear-gradient(90deg,#fff,var(--cyan) 60%,var(--blue));-webkit-background-clip:text;background-clip:text;color:transparent}\nheader p{color:var(--mut)}\n.warn{display:flex;gap:12px;align-items:flex-start;background:rgba(250,204,21,.08);border:1px solid rgba(250,204,21,.4);border-radius:14px;padding:14px 16px;margin-bottom:12px;color:#fde68a;line-height:1.8}\n.warn.req{background:rgba(34,211,238,.07);border-color:rgba(34,211,238,.35);color:#b6f3ff}\n.warn b{color:#fff}\n.grid{display:grid;grid-template-columns:1fr 1.15fr;gap:18px;margin-top:18px}\n@media(max-width:860px){.grid{grid-template-columns:1fr}}\n.card{background:linear-gradient(180deg,rgba(15,30,66,.85),rgba(8,16,38,.9));border:1px solid var(--line);border-radius:20px;padding:20px;box-shadow:0 0 40px rgba(21,96,255,.12);backdrop-filter:blur(6px)}\n.card h2{font-size:17px;margin-bottom:14px;display:flex;align-items:center;gap:8px}\n.card h2::before{content:\"\";width:4px;height:18px;border-radius:4px;background:linear-gradient(var(--cyan),var(--blue))}\n.drop{position:relative;border:2px dashed rgba(34,211,238,.45);border-radius:16px;min-height:290px;display:grid;place-items:center;text-align:center;cursor:pointer;overflow:hidden;transition:.25s;background:rgba(21,96,255,.05)}\n.drop:hover,.drop.over{border-color:var(--cyan);background:rgba(34,211,238,.09);box-shadow:inset 0 0 40px rgba(34,211,238,.12)}\n.drop .ico{font-size:42px;filter:drop-shadow(0 0 12px var(--cyan))}\n.drop small{color:var(--mut)}\n.drop img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#000;display:none}\n.scan{position:absolute;left:0;right:0;height:3px;background:linear-gradient(90deg,transparent,var(--cyan),transparent);box-shadow:0 0 22px 6px rgba(34,211,238,.7);display:none;animation:scan 1.8s linear infinite}\n.drop.busy .scan{display:block}\n.chk{display:flex;gap:10px;align-items:flex-start;margin:14px 0;color:var(--mut);font-size:14px;cursor:pointer;line-height:1.7}\n.chk input{accent-color:var(--cyan);width:18px;height:18px;margin-top:4px}\n.btn{width:100%;border:0;border-radius:12px;padding:14px;font:800 16px Cairo;color:#fff;cursor:pointer;background:linear-gradient(90deg,var(--blue),#0ea5e9);box-shadow:0 8px 28px rgba(21,96,255,.45);transition:.2s}\n.btn:disabled{opacity:.4;cursor:not-allowed;box-shadow:none}\n.btn:not(:disabled):hover{transform:translateY(-2px)}\n.btn.ghost{background:transparent;border:1px solid var(--line);box-shadow:none;margin-top:8px;color:var(--mut);padding:10px;font-size:14px}\n.err{color:#fca5a5;font-size:14px;margin-top:10px;min-height:20px}\n.idle{display:grid;place-items:center;min-height:420px;text-align:center;color:var(--mut)}\n.idle .ring{width:110px;height:110px;border-radius:50%;border:2px solid var(--line);border-top-color:var(--cyan);margin:0 auto 14px;animation:spin 3s linear infinite}\n#res{display:none}\n.verdict{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:14px 16px;border-radius:14px;border:1px solid;margin-bottom:14px}\n.verdict.neg{background:rgba(34,197,94,.1);border-color:rgba(34,197,94,.5)}\n.verdict.pos{background:rgba(239,68,68,.1);border-color:rgba(239,68,68,.55)}\n.verdict .v{font-size:30px;font-weight:800}\n.neg .v{color:var(--g)}.pos .v{color:var(--r)}\n.verdict .s{color:var(--mut);font-size:13px}\n.conf{text-align:center}\n.conf b{font:500 26px 'JetBrains Mono',monospace;color:#fff;display:block}\n.conf span{font-size:12px;color:var(--mut)}\n.gwrap{display:grid;grid-template-columns:1.2fr 1fr;gap:14px;align-items:center}\n@media(max-width:560px){.gwrap{grid-template-columns:1fr}}\n.gauge{direction:ltr}\n.gauge svg{width:100%;display:block}\n#needle{transform-origin:120px 120px;transition:transform 1.6s cubic-bezier(.2,.9,.25,1.1)}\n.gnum{text-align:center;margin-top:-6px}\n.gnum b{font:500 34px 'JetBrains Mono',monospace}\n.gnum span{display:block;font-size:12px;color:var(--mut)}\n.legend{display:grid;gap:8px;font-size:13px}\n.legend div{display:flex;gap:9px;align-items:flex-start;padding:7px 9px;border-radius:10px;background:rgba(255,255,255,.03);border:1px solid transparent;line-height:1.5}\n.legend div.on{border-color:var(--line);background:rgba(255,255,255,.08)}\n.legend i{flex:none;width:13px;height:13px;border-radius:4px;margin-top:4px}\n.legend b{display:block;color:#fff}.legend span{color:var(--mut)}\n.cta{display:none;margin-top:18px;text-align:center;padding:22px 18px;border-radius:18px;border:1px solid var(--line);background:linear-gradient(135deg,rgba(21,96,255,.18),rgba(34,211,238,.08))}\n.cta p{font-size:16px;line-height:1.9;margin-bottom:14px}\n.cta a{display:inline-block;background:#fff;border-radius:14px;padding:12px 22px;box-shadow:0 0 34px rgba(34,211,238,.35);transition:.25s}\n.cta a:hover{transform:translateY(-3px) scale(1.03);box-shadow:0 0 50px rgba(34,211,238,.6)}\n.cta img{height:48px;display:block}\n.cta small{display:block;margin-top:10px;color:var(--mut)}\nfooter{text-align:center;color:var(--mut);font-size:12px;margin-top:26px}\n@keyframes scan{0%{top:0}100%{top:100%}}\n@keyframes spin{to{transform:rotate(360deg)}}\n@keyframes pulse{50%{opacity:.3}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n<header>\n  <span class=\"chip\"><i></i>AI · DEEP LEARNING · RESNET50</span>\n  <h1>تحليل أشعة الصدر بالذكاء الاصطناعي</h1>\n  <p>ارفع صورة أشعة صدر (Chest X-Ray) ليقوم النموذج بتحليلها والكشف عن الالتهاب الرئوي</p>\n</header>\n\n<div class=\"warn\"><span>⚠️</span><div><b>تنبيه:</b> هذا موديل تجريبي تم تدريبه على داتا تجريبية، والنتيجة النهائية لا تغني عن استشارة طبيب.</div></div>\n<div class=\"warn req\"><span>🩻</span><div><b>شرط الإدخال:</b> يجب أن تكون الصورة <b>أشعة صدر X-Ray</b> (أمامية)، بصيغة JPG أو PNG. أي صورة أخرى ستعطي نتيجة غير صحيحة.</div></div>\n\n<div class=\"grid\">\n  <section class=\"card\">\n    <h2>إدخال الصورة</h2>\n    <label class=\"drop\" id=\"drop\">\n      <input type=\"file\" id=\"file\" accept=\"image/png,image/jpeg\" hidden>\n      <div id=\"ph\"><div class=\"ico\">📤</div><p><b>اسحب الصورة هنا</b> أو اضغط للاختيار</p><small>JPG / PNG — حتى 10MB</small></div>\n      <img id=\"prev\" alt=\"معاينة الأشعة\"><div class=\"scan\"></div>\n    </label>\n    <label class=\"chk\"><input type=\"checkbox\" id=\"ok\"><span>أؤكد أن الصورة المرفوعة هي أشعة صدر (Chest X-Ray) وأن النتيجة استرشادية فقط.</span></label>\n    <button class=\"btn\" id=\"go\" disabled>تحليل الصورة</button>\n    <button class=\"btn ghost\" id=\"reset\" style=\"display:none\">إعادة تعيين</button>\n    <div class=\"err\" id=\"err\"></div>\n  </section>\n\n  <section class=\"card\">\n    <h2>نتيجة التحليل</h2>\n    <div class=\"idle\" id=\"idle\"><div><div class=\"ring\"></div><p>في انتظار الصورة…<br><small>ستظهر النتيجة ومؤشر الاحتمال هنا</small></p></div></div>\n    <div id=\"res\">\n      <div class=\"verdict\" id=\"verdict\">\n        <div><div class=\"v\" id=\"vt\"></div><div class=\"s\" id=\"vs\"></div></div>\n        <div class=\"conf\"><b id=\"conf\">0%</b><span>نسبة الثقة</span></div>\n      </div>\n      <div class=\"gwrap\">\n        <div>\n          <div class=\"gauge\">\n            <svg viewBox=\"0 0 240 150\" id=\"gsvg\">\n              <g id=\"arcs\"></g>\n              <g id=\"needle\"><line x1=\"120\" y1=\"120\" x2=\"120\" y2=\"42\" stroke=\"#fff\" stroke-width=\"3.5\" stroke-linecap=\"round\"/><circle cx=\"120\" cy=\"120\" r=\"9\" fill=\"#fff\"/><circle cx=\"120\" cy=\"120\" r=\"4\" fill=\"#0b1630\"/></g>\n              <text x=\"14\" y=\"142\" fill=\"#8fa3c7\" font-size=\"11\">0%</text><text x=\"206\" y=\"142\" fill=\"#8fa3c7\" font-size=\"11\">100%</text>\n            </svg>\n          </div>\n          <div class=\"gnum\"><b id=\"pct\">0%</b><span>احتمال الإصابة بالالتهاب الرئوي</span></div>\n        </div>\n        <div class=\"legend\" id=\"legend\"></div>\n      </div>\n    </div>\n  </section>\n</div>\n\n<div class=\"cta\" id=\"cta\">\n  <p>إذا أردت موديل بكفاءة عالية يساعدك في عملك،<br><b>تواصل معنا</b></p>\n  <a href=\"https://autoolab.github.io/AUTO-lab/\" target=\"_blank\" rel=\"noopener\" aria-label=\"AUTOlab\"><img src=\"data:image/png;base64,\" alt=\"AUTOlab\"></a>\n  <small>اضغط على الشعار لزيارة صفحتنا</small>\n</div>\n<footer>AUTOlab · نموذج تجريبي للأغراض التعليمية فقط</footer>\n</div>\n\n<script>\nconst API_URL = \"/predict\";   // غيّره لو الباك اند على عنوان آخر\n// الرد المتوقع: { \"label\":\"Positive (Pneumonia)\" | \"Negative (Normal)\", \"confidence\":0.93, \"pneumonia_probability\":0.93 }\n\nconst ZONES=[\n {a:0,b:30,c:'#22c55e',t:'منخفض',d:'الصورة أقرب للحالة السليمة'},\n {a:30,b:50,c:'#facc15',t:'غير حاسم',d:'احتمال متوسط، يحتاج مراجعة'},\n {a:50,b:75,c:'#fb923c',t:'مرتفع',d:'مؤشرات التهاب رئوي محتملة'},\n {a:75,b:100,c:'#ef4444',t:'مرتفع جدًا',d:'احتمال قوي للإصابة'}];\nconst $=id=>document.getElementById(id);\nconst pt=(p,r)=>{const t=Math.PI*(1-p/100);return[120+r*Math.cos(t),120-r*Math.sin(t)]};\n$('arcs').innerHTML=ZONES.map(z=>{const[x1,y1]=pt(z.a+.8,92),[x2,y2]=pt(z.b-.8,92);\n return `<path d=\"M${x1} ${y1} A92 92 0 0 1 ${x2} ${y2}\" stroke=\"${z.c}\" stroke-width=\"18\" fill=\"none\" stroke-linecap=\"butt\"/>`}).join('');\n$('legend').innerHTML=ZONES.map((z,i)=>`<div id=\"z${i}\"><i style=\"background:${z.c}\"></i><p><b>${z.a}–${z.b}% · ${z.t}</b><span>${z.d}</span></p></div>`).join('');\n\nlet file=null;\nconst sync=()=>$('go').disabled=!(file&&$('ok').checked);\n$('ok').onchange=sync;\nfunction setFile(f){\n  $('err').textContent='';\n  if(!f)return;\n  if(!/^image\\/(png|jpeg)$/.test(f.type)){$('err').textContent='الرجاء رفع صورة بصيغة JPG أو PNG.';return}\n  if(f.size>10*1024*1024){$('err').textContent='حجم الصورة أكبر من 10MB.';return}\n  file=f;const u=URL.createObjectURL(f);\n  $('prev').src=u;$('prev').style.display='block';$('ph').style.display='none';$('reset').style.display='block';sync();\n}\n$('file').onchange=e=>setFile(e.target.files[0]);\nconst d=$('drop');\n['dragenter','dragover'].forEach(e=>d.addEventListener(e,ev=>{ev.preventDefault();d.classList.add('over')}));\n['dragleave','drop'].forEach(e=>d.addEventListener(e,ev=>{ev.preventDefault();d.classList.remove('over')}));\nd.addEventListener('drop',e=>setFile(e.dataTransfer.files[0]));\n$('reset').onclick=()=>{file=null;$('file').value='';$('prev').style.display='none';$('ph').style.display='block';$('reset').style.display='none';\n $('res').style.display='none';$('cta').style.display='none';$('idle').style.display='grid';$('needle').style.transform='rotate(-90deg)';sync()};\n\nasync function predict(f){\n  try{\n    const fd=new FormData();fd.append('file',f);\n    const ac=new AbortController();setTimeout(()=>ac.abort(),30000);\n    const r=await fetch(API_URL,{method:'POST',body:fd,signal:ac.signal});\n    if(!r.ok)throw new Error(r.status);\n    return{data:await r.json()};\n  }catch(e){\n    return{error:true};\n  }\n}\n$('go').onclick=async()=>{\n  $('go').disabled=true;$('go').textContent='جارٍ التحليل…';d.classList.add('busy');\n  const out=await predict(file);\n  d.classList.remove('busy');$('go').textContent='تحليل الصورة';sync();\n  if(out.error){$('err').textContent='تعذر الاتصال بالسيرفر أو فشل التحليل. تأكد من تشغيل الباك اند وأن الصورة صالحة ثم حاول مرة أخرى.';return}\n  const data=out.data;\n  let p=data.pneumonia_probability;\n  if(p==null){const pos=/pos|pneu/i.test(data.label||'');p=pos?data.confidence:1-data.confidence}\n  render(p*100,(data.confidence??Math.max(p,1-p))*100);\n};\nfunction render(p,conf){\n  const pos=p>=50;\n  $('idle').style.display='none';$('res').style.display='block';\n  $('verdict').className='verdict '+(pos?'pos':'neg');\n  $('vt').textContent=pos?'إيجابي (Positive)':'سلبي (Negative)';\n  $('vs').textContent=pos?'اشتباه وجود التهاب رئوي':'لا توجد مؤشرات التهاب رئوي';\n  ZONES.forEach((z,i)=>$('z'+i).classList.toggle('on',p>=z.a&&(p<z.b||(i==3&&p<=100))));\n  $('needle').style.transform='rotate(-90deg)';\n  requestAnimationFrame(()=>requestAnimationFrame(()=>$('needle').style.transform=`rotate(${p/100*180-90}deg)`));\n  const t0=performance.now();\n  (function tick(t){const k=Math.min(1,(t-t0)/1500);\n    $('pct').textContent=(p*k).toFixed(1)+'%';$('conf').textContent=(conf*k).toFixed(1)+'%';\n    if(k<1)requestAnimationFrame(tick)})(t0);\n  $('cta').style.display='block';\n  $('res').scrollIntoView({behavior:'smooth',block:'nearest'});\n}\n</script>\n</body>\n</html>\n"

app=FastAPI(title="AUTOlab Pneumonia Detection")

@app.get("/",response_class=HTMLResponse)
def home():
    return HTMLResponse(DASHBOARD_HTML)

@app.get("/health")
def health():
    return {"status":"ok","model_loaded":True,"model_source":MODEL_SOURCE}

@app.post("/predict")
async def predict(file:UploadFile=File(...)):
    if file.content_type not in {"image/jpeg","image/png"}:
        raise HTTPException(status_code=400,detail="Only JPG and PNG images are allowed.")
    raw=await file.read(MAX_UPLOAD_BYTES+1)
    if len(raw)>MAX_UPLOAD_BYTES:
        raise HTTPException(status_code=413,detail="Image is larger than 10MB.")
    try:
        img=Image.open(io.BytesIO(raw))
        img.verify()
        img=Image.open(io.BytesIO(raw)).convert("RGB")
    except (UnidentifiedImageError,OSError,ValueError):
        raise HTTPException(status_code=400,detail="The uploaded file is not a valid image.")
    x=transform(img).unsqueeze(0).to(DEVICE)
    with torch.inference_mode():
        probs=torch.softmax(MODEL(x),dim=1)[0]
    p=float(probs[1])
    pos=p>=0.5
    return {"label":"Positive (Pneumonia)" if pos else "Negative (Normal)",
            "confidence":p if pos else 1-p,
            "pneumonia_probability":p}

if __name__=="__main__":
    import uvicorn
    uvicorn.run(app,host="0.0.0.0",port=int(os.getenv("PORT","8000")))
